const Primitive = Cesium.Primitive;
/**
 * Draws the axes of a reference frame defined by a matrix that transforms to world
 * coordinates, i.e., Earth's WGS84 coordinates.  The most prominent example is
 * a primitives <code>modelMatrix</code>.
 * <p>
 * The X axis is red; Y is green; and Z is blue.
 * </p>
 * <p>
 * This is for debugging only; it is not optimized for production use.
 * </p>
 *
 * @alias DebugModelMatrixPrimitive
 * @constructor
 *
 * @param {Object} [options] Object with the following properties:
 * @param {Number} [options.length=10000000.0] The length of the axes in meters.
 * @param {Number} [options.width=2.0] The width of the axes in pixels.
 * @param {Matrix4} [options.modelMatrix=Matrix4.IDENTITY] The 4x4 matrix that defines the reference frame, i.e., origin plus axes, to visualize.
 * @param {Boolean} [options.show=true] Determines if this primitive will be shown.
 * @param {Object} [options.id] A user-defined object to return when the instance is picked with {@link Scene#pick}
 *
 * @example
 * primitives.add(new Cesium.DebugModelMatrixPrimitive({
 *   modelMatrix : primitive.modelMatrix,  // primitive to debug
 *   length : 100000.0,
 *   width : 10.0
 * }));
 */
class DebugModelMatrixPrimitive {
  constructor(options) {
    options = defaultValue(options, defaultValue.EMPTY_OBJECT);

    /**
     * The length of the axes in meters.
     *
     * @type {Number}
     * @default 10000000.0
     */
    this.length = defaultValue(options.length, 10000000.0);
    this._length = undefined;

    /**
     * The width of the axes in pixels.
     *
     * @type {Number}
     * @default 2.0
     */
    this.width = defaultValue(options.width, 2.0);
    this._width = undefined;

    /**
     * Determines if this primitive will be shown.
     *
     * @type Boolean
     * @default true
     */
    this.show = defaultValue(options.show, true);

    /**
     * The 4x4 matrix that defines the reference frame, i.e., origin plus axes, to visualize.
     *
     * @type {Matrix4}
     * @default {@link Matrix4.IDENTITY}
     */
    this.modelMatrix = Matrix4.clone(
      defaultValue(options.modelMatrix, Matrix4.IDENTITY)
    );
    this._modelMatrix = new Matrix4();

    /**
     * User-defined value returned when the primitive is picked.
     *
     * @type {*}
     * @default undefined
     *
     * @see Scene#pick
     */
    this.id = options.id;
    this._id = undefined;

    this._primitive = undefined;
  }
  /**
   * @private
   */
  update(frameState) {
    if (!this.show) {
      return;
    }

    if (
      !Cesium.defined(this._primitive) ||
      !Matrix4.equals(this._modelMatrix, this.modelMatrix) ||
      this._length !== this.length ||
      this._width !== this.width ||
      this._id !== this.id
    ) {
      this._modelMatrix = Matrix4.clone(this.modelMatrix, this._modelMatrix);
      this._length = this.length;
      this._width = this.width;
      this._id = this.id;

      if (Cesium.defined(this._primitive)) {
        this._primitive.destroy();
      }

      // Workaround projecting (0, 0, 0)
      if (
        this.modelMatrix[12] === 0.0 &&
        this.modelMatrix[13] === 0.0 &&
        this.modelMatrix[14] === 0.0
      ) {
        this.modelMatrix[14] = 0.01;
      }

      const x = new Cesium.GeometryInstance({
        geometry: new Cesium.PolylineGeometry({
          positions: [Cartesian3.ZERO, Cartesian3.UNIT_X],
          width: this.width,
          vertexFormat: PolylineMaterialAppearance.VERTEX_FORMAT,
          //   colors: [Color.RED,Color.RED],
          arcType: ArcType.NONE,
        }),
        modelMatrix: Matrix4.multiplyByUniformScale(
          this.modelMatrix,
          this.length,
          new Matrix4()
        ),
        id: this.id,
        pickPrimitive: this,
      });
      const y = new Cesium.GeometryInstance({
        geometry: new Cesium.PolylineGeometry({
          positions: [Cartesian3.ZERO, Cartesian3.UNIT_Y],
          width: this.width,
          vertexFormat: PolylineMaterialAppearance.VERTEX_FORMAT,
          //   colors: [Color.RED,Color.RED],
          arcType: ArcType.NONE,
        }),
        modelMatrix: Matrix4.multiplyByUniformScale(
          this.modelMatrix,
          this.length,
          new Matrix4()
        ),
        id: this.id,
        pickPrimitive: this,
      });
      const z = new Cesium.GeometryInstance({
        geometry: new Cesium.PolylineGeometry({
          positions: [Cartesian3.ZERO, Cartesian3.UNIT_Z],
          width: this.width,
          vertexFormat: PolylineMaterialAppearance.VERTEX_FORMAT,
          //   colors: [Color.RED,Color.RED],
          arcType: ArcType.NONE,
        }),
        modelMatrix: Matrix4.multiplyByUniformScale(
          this.modelMatrix,
          this.length,
          new Matrix4()
        ),
        id: this.id,
        pickPrimitive: this,
      });

      let m = new Cesium.PolylineMaterialAppearance({
        material:Cesium.Material.fromType(Cesium.Material.PolylineArrowType,{color:Cesium.Color.RED})
      });
      this._primitive = new Primitive({
        geometryInstances: [x, y, z],
        // appearance: new PolylineColorAppearance(),
        appearance: m,
        depthFailAppearance:m,
        asynchronous: false,
      });
    }

    this._primitive.update(frameState);
  }

  /**
   * Destroys the WebGL resources held by this object.  Destroying an object allows for deterministic
   * release of WebGL resources, instead of relying on the garbage collector to destroy this object.
   * <p>
   * Once an object is destroyed, it should not be used; calling any function other than
   * <code>isDestroyed</code> will result in a {@link DeveloperError} exception.  Therefore,
   * assign the return value (<code>undefined</code>) to the object as done in the example.
   * </p>
   *
   * @exception {DeveloperError} This object was destroyed, i.e., destroy() was called.
   *
   * @example
   * p = p && p.destroy();
   *
   * @see DebugModelMatrixPrimitive#isDestroyed
   */
  destroy() {
    this._primitive = this._primitive && this._primitive.destroy();
    return Cesium.destroyObject(this);
  }
}

var scene = viewer.scene;

var localFrames = [
  {
    pos: Cesium.Cartesian3.fromDegrees(-123.075, 44.045, 5000.0),
    converter: Cesium.Transforms.eastNorthUpToFixedFrame,
    comments: "Classical East North Up\nlocal Frame",
  },
  {
    pos: Cesium.Cartesian3.fromDegrees(-123.075, 44.05, 5500.0),
    converter: Cesium.Transforms.localFrameToFixedFrameGenerator(
      "north",
      "west"
    ),
    comments: "North West Up\nlocal Frame",
  },
  {
    pos: Cesium.Cartesian3.fromDegrees(-123.075, 44.04, 4500.0),
    converter: Cesium.Transforms.localFrameToFixedFrameGenerator("south", "up"),
    comments: "South Up West\nlocal Frame",
  },
  {
    pos: Cesium.Cartesian3.fromDegrees(-123.075, 44.05, 4500.0),
    converter: Cesium.Transforms.localFrameToFixedFrameGenerator("up", "east"),
    comments: "Up East North\nlocal Frame",
  },
  {
    pos: Cesium.Cartesian3.fromDegrees(-123.075, 44.04, 5500.0),
    converter: Cesium.Transforms.localFrameToFixedFrameGenerator(
      "down",
      "east"
    ),
    comments: "Down East South\nlocal Frame",
  },
];

var hprRollZero = new Cesium.HeadingPitchRoll();

for (var i = 0; i < localFrames.length; i++) {
  var position = localFrames[i].pos;
  var converter = localFrames[i].converter;

  var modelMatrix = Cesium.Transforms.headingPitchRollToFixedFrame(
    position,
    hprRollZero,
    Cesium.Ellipsoid.WGS84,
    converter
  );
  //绘制由变换为世界坐标的矩阵定义的参考系的坐标轴，
  // 即，地球的WGS84坐标。最突出的例子是原语模型矩阵。
  // X轴是红色的;Y是绿色的;Z是蓝色的。
  scene.primitives.add(
    new DebugModelMatrixPrimitive({
      modelMatrix: modelMatrix,
      length: 300.0,
      width: 10.0,
    })
  );
}
